package org.zstack.sdk.zwatch.thirdparty.api;



public class PushThirdpartyAlertResult {
    public java.lang.String platformUuid;
    public void setPlatformUuid(java.lang.String platformUuid) {
        this.platformUuid = platformUuid;
    }
    public java.lang.String getPlatformUuid() {
        return this.platformUuid;
    }

    public java.lang.String originalAlertUuid;
    public void setOriginalAlertUuid(java.lang.String originalAlertUuid) {
        this.originalAlertUuid = originalAlertUuid;
    }
    public java.lang.String getOriginalAlertUuid() {
        return this.originalAlertUuid;
    }

    public boolean duplicate;
    public void setDuplicate(boolean duplicate) {
        this.duplicate = duplicate;
    }
    public boolean getDuplicate() {
        return this.duplicate;
    }

}
